<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nine Squares, One Smile</title>
<style>
:root{--paper:#f3efdf;--ink:#242720;--red:#c94023;--blue:#234ba2;--yellow:#e7b735}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:"Trebuchet MS",sans-serif}button,input,select{font:inherit}button{cursor:pointer;min-height:44px;border:1px solid var(--ink);background:transparent;color:inherit;padding:10px 14px}button:hover{background:#e2dccb}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--blue);outline-offset:4px}a{color:inherit;text-underline-offset:4px}header{max-width:1280px;margin:auto;padding:24px 30px 0}.top{display:flex;justify-content:space-between;border-bottom:2px solid;padding-bottom:14px;gap:16px;font:12px "Courier New",monospace;letter-spacing:1px}.intro{display:grid;grid-template-columns:1fr 280px;align-items:end;gap:20px;padding:32px 0}h1{font-family:Georgia,serif;font-weight:normal;font-size:clamp(44px,6.6vw,92px);line-height:.97;letter-spacing:-3px;margin:0}h1 em{color:var(--red)}.intro p{line-height:1.6;margin:0;font-size:15px}.workshop{max-width:1280px;margin:auto;padding:0 30px 40px;display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:40px}.poster{background:#fffcf0;box-shadow:8px 10px 0 #2427201c;padding:clamp(16px,3vw,38px);align-self:start}.poster-top{display:flex;justify-content:space-between;align-items:center;font:12px "Courier New",monospace;margin-bottom:18px}.board{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;aspect-ratio:1}.tile{padding:0;min-height:0;position:relative;aspect-ratio:1;border:0;overflow:hidden;background:#f3efdf}.tile[aria-pressed=true]{outline:3px solid var(--ink);outline-offset:2px;z-index:1}.tile:focus-visible{outline:4px solid var(--blue)}.tile i{display:block;position:absolute;inset:0;pointer-events:none;background-size:300% 300%;transition:transform .18s}.tile span{position:absolute;bottom:4px;left:4px;font:10px monospace;background:#fffcf0d9;padding:2px 4px;pointer-events:none}.poster h2{font:clamp(24px,4vw,44px) Georgia,serif;margin:24px 0 8px;overflow-wrap:anywhere}.poster-foot{font:11px "Courier New",monospace;display:flex;justify-content:space-between;gap:8px;border-top:1px solid;padding-top:12px}.panel{border-top:4px solid var(--ink)}.label{font:11px "Courier New",monospace;letter-spacing:1px;text-transform:uppercase;margin:18px 0 10px}.panel h2{font:28px Georgia,serif;margin:12px 0}.help{font-size:14px;line-height:1.5}.tools{display:grid;grid-template-columns:1fr 1fr;gap:8px}.tools button[aria-pressed=true]{background:var(--ink);color:var(--paper)}.swatches{display:flex;gap:10px}.swatch{width:42px;height:42px;min-height:42px;padding:0;border-radius:50%;border:2px solid var(--ink);box-shadow:inset 0 0 0 3px var(--paper)}.swatch[aria-pressed=true]{outline:2px solid var(--ink);outline-offset:3px}.row{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}input,select{width:100%;padding:12px;border:1px solid var(--ink);color:var(--ink);background:transparent;border-radius:0}input{font-size:16px}.brief{margin-top:24px;padding:18px;background:#e5e1d0}.brief h3{font:22px Georgia,serif;margin:10px 0}.brief p{font-size:14px;line-height:1.5}.primary{background:var(--red);color:#fff;border-color:var(--red)}.primary:hover{background:#a6321b}.full{width:100%;margin-top:10px}#status{min-height:44px;line-height:1.5;font-size:14px}.source{max-width:1280px;margin:auto;padding:24px 30px 40px;border-top:1px solid;display:grid;grid-template-columns:1fr 1fr;gap:40px;font-size:14px;line-height:1.6}.source img{width:110px;aspect-ratio:1;float:left;margin-right:16px}.source p{margin:0}.chip{display:inline-block;background:var(--yellow);padding:4px 8px;transform:rotate(-3deg);font:11px monospace}noscript{display:block;padding:24px}@media(max-width:780px){header{padding:18px 18px 0}.intro{grid-template-columns:1fr;padding:25px 0}.intro p{max-width:460px}.workshop{padding:0 18px 30px;grid-template-columns:1fr;gap:28px}.panel{max-width:600px}.source{grid-template-columns:1fr;padding:22px 18px;gap:20px}.top{