<header><div class="top"><a href="index.php">CHLOE READS JON ↖</a><span>COMPOSITION PLAY / No. 01</span></div><div class="intro"><h1>Nine squares.<br>One <em>smile.</em></h1><p>A tiny poster studio for a big idea: a few shapes in the right places can make someone happy. Pick a square. Make your move.</p></div></header>
<noscript>This studio needs JavaScript. <a href="?source=1">Read Jon's post about Dave's design work.</a></noscript>
<main class="workshop"><section class="poster" aria-label="Your poster preview"><div class="poster-top"><span>SMALL PRINTS / BIG IDEAS</span><span class="chip">MAKE SOME JOY</span></div><div class="board" id="board" aria-label="Nine editable squares"></div><h2 id="posterTitle">A little room for wonder</h2><div class="poster-foot"><span>AN EXPERIMENT IN LOOKING</span><span>NINE SQUARES, ONE SMILE</span></div></section>
<aside class="panel"><div class="label">01 / Your materials</div><h2 id="selection">Square 5 is yours.</h2><p class="help">Tap a square, then choose its material. Each picture square is a crop of the fox print below. No dragging or tiny handles.</p>
<div class="tools" id="materials"><button data-kind="art">Picture crop</button><button data-kind="blank">Empty paper</button><button data-kind="disc">Circle</button><button data-kind="stripe">Diagonal</button><button data-kind="solid">Solid ink</button></div>
<div class="label">Ink colour</div><div class="swatches" id="swatches"></div>
<div class="row"><button id="rotate">Rotate ↻</button><button id="crop">Next crop →</button><button id="undo" disabled>Undo</button></div>
<label class="label" for="title">Your poster title</label><input id="title" maxlength="54" value="A little room for wonder">
<div class="brief"><div class="label" style="margin-top:0">02 / A small creative brief</div><label for="briefSelect">Choose an experiment</label><select id="briefSelect"><option value="space">Let it breathe</option><option value="focus">One small hero</option><option value="rhythm">A diagonal conversation</option><option value="free">Freestyle</option></select><h3 id="briefTitle"></h3><p id="briefText"></p><button id="check">Check the brief</button><p id="verdict" aria-live="polite"></p></div>
<div class="label">03 / Off the press</div><button class="primary full" id="download">Save poster as PNG ↓</button><div class="row"><button id="reset">Restore original</button><button id="clear">Blank canvas</button></div><p id="status" role="status" aria-live="polite">Your changes stay in this browser when storage is available.</p></aside></main>
<footer class="source"><div><img src="?art=1" alt="Original cut-paper fox print in orange, cobalt and cream"><p><strong>The fox is your raw material.</strong><br>Cut it up, leave breathing room, interrupt it with a circle. This original AI-generated print was made for this studio; it is not Dave's artwork.</p></div><p>Inspired by Jon's <a href="?source=1">My creative bro: designer Dave Aquino</a>, which shares Dave's grid compositions, colour studies, and wish to make people smile through design. The briefs here test simple constraints, not whether your art is “good”. That's your call.</p></footer>
<script>
'use strict';
const $=id=>document.getElementById(id), inks=['#c94023','#234ba2','#e7b735','#242720'], names=['Vermilion','Cobalt','Marigold','Ink'], paper='#f3efdf';
let tiles=Array.from({length:9},(_,i)=>({kind:'art',crop:i,rotation:0,color:0})),selected=4,history=[];
const original=()=>Array.from({length:9},(_,i)=>({kind:'art',crop:i,rotation:0,color:0}));
const validTile=t=>t&&['art','blank','disc','stripe','solid'].includes(t.kind)&&Number.isInteger(t.crop)&&t.crop>=0&&t.crop<9&&Number.isInteger(t.rotation)&&t.rotation>=0&&t.rotation<4&&Number.isInteger(t.color)&&t.color>=0&&t.color<4;
try{const s=JSON.parse(localStorage.getItem('nine-squares-v1'));if(s&&Array.isArray(s.tiles)&&s.tiles.length===9&&s.tiles.every(validTile)){tiles=s.tiles;if(typeof s.title==='string')$('title').value=s.title.slice(0,54);}}catch(e){}
const image=new Image();image.src='?art=1';
image.onerror=()=>{$('status').textContent='The print could not load. Shapes still work; try reloading for the fox.';$('download').disabled=true;};
const briefs={space:['Let it breathe','Leave at least three squares as empty paper. See how the busy squares suddenly have somewhere to look.'],focus:['One small hero','Use exactly one picture square, in the centre, and at least four empty paper squares. Frame your tiny hero with shapes if you like.'],rhythm:['A diagonal conversation','Put picture crops at top left, centre, and bottom right, with no other picture squares. Leave at least three empty squares. Let the eye travel.'],free:['Freestyle','No rules. Make something you would put on the fridge. A very small gallery with excellent snacks.']};
function announce(s){$('status').textContent=s}
function persist(){try{localStorage.setItem('nine-squares-v1',JSON.stringify({tiles,title:$('title').value}))}catch(e){announce('Storage is unavailable. You can still save a PNG.');}}
function snapshot(){history.push(JSON.stringify({tiles,title:$('title').value}));if(history.length>60)history.shift();$('undo').disabled=false;$('verdict').textContent='';}
function materialStyle(t){const c=inks[t.color];if(t.kind==='art')return {backgroundImage:'url("?art=1")',backgroundPosition:((t.crop%3)*50)+'% '+(Math.floor(t.crop/3)*50)+'%',backgroundColor:paper};if(t.kind==='disc')return {backgroundImage:'radial-gradient(circle, '+c+' 0 52%, transparent 53%)',backgroundSize:'100% 100%',backgroundColor:paper};if(t.kind==='stripe')return {backgroundImage:'linear-gradient(135deg, transparent 30%, '+c+' 30% 70%, transparent 70%)',backgroundSize:'100% 100%',backgroundColor:paper};return {backgroundColor:t.kind==='solid'?c:paper,backgroundImage:'none'};}
function render(){[...$('board').children].forEach((b,i)=>{const t=tiles[i],el=b.firstChild;el.removeAttribute('style');Object.assign(el.style,materialStyle(t),{transform:'rotate('+t.rotation*90+'deg)'});b.setAttribute('aria-pressed',i===selected?'true':'false');b.setAttribute('aria-label','Square '+(i+1)+', '+t.kind+(t.kind==='art'?', crop '+(t.crop+1):''));});$('selection').textContent='Square '+(selected+1)+' is yours.';document.querySelectorAll('[data-kind]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.kind===tiles[selected].kind));[...$('swatches').children].forEach((b,i)=>b.setAttribute('aria-pressed',i===tiles[selected].color));$('posterTitle').textContent=$('title').value.trim()||'Untitled, but promising';$('undo').disabled=!history.length;}
for(let i=0;i<9;i++){const b=document.createElement('button'),art=document.createElement('i'),n=document.createElement('span');art.setAttribute('aria-hidden','true');n.textContent=i+1;n.setAttribute('aria-hidden','true');b.className='tile';b.append(art,n);b.onclick=()=>{selected=i;render()};b.onkeydown=e=>{const moves={ArrowRight:1,ArrowLeft:-1,ArrowDown:3,ArrowUp:-3};if(e.key in moves){e.preventDefault();selected=(i+moves[e.key]+9)%9;render();$('board').children[selected].focus();}};$('board').append(b);}
inks.forEach((c,i)=>{const b=document.createElement('button');b.className='swatch';b.style.background=c;b.setAttribute('aria-label',names[i]+' ink');b.onclick=()=>{snapshot();tiles[selected].color=i;render();persist();if(['art','blank'].includes(tiles[selected].kind))announce('Ink chosen. Choose Circle, Diagonal or Solid ink to see it.');};$('swatches').append(b);});
$('materials').onclick=e=>{if(!e.target.dataset.kind)return;snapshot();tiles[selected].kind=e.target.dataset.kind;render();persist();};
$('rotate').onclick=()=>{snapshot();tiles[selected].rotation=(tiles[selected].rotation+1)%4;render();persist();};
$('crop').onclick=()=>{snapshot();tiles[selected].kind='art';tiles[selected].crop=(tiles[selected].crop+1)%9;render();persist();};
$('undo').onclick=()=>{if(!history.length)return;const s=JSON.parse(history.pop());tiles=s.tiles;$('title').value=s.title;$('verdict').textContent='';render();persist();announce('One move undone.');};
$('title').oninput=()=>{render();persist()};
$('reset').onclick=()=>{snapshot();tiles=original();$('title').value='A little room for wonder';render();persist();announce('The original fox print is back.');};
$('clear').onclick=()=>{snapshot();tiles=original().map(t=>({...t,kind:'blank'}));render();persist();announce('Fresh paper. Every square is empty.');};
function brief(){const b=briefs[$('briefSelect').value];$('briefTitle').textContent=b[0];$('briefText').textContent=b[1];$('verdict').textContent='';}
$('briefSelect').onchange=brief;
$('check').onclick=()=>{const k=$('briefSelect').value,blank=tiles.filter(t=>t.kind==='blank').length,art=tiles.map((t,i)=>t.kind==='art'?i:-1).filter(i=>i>=0);let ok=k==='free'||k==='space'&&blank>=3||k==='focus'&&art.length===1&&art[0]===4&&blank>=4||k==='rhythm'&&art.join(',')==='0,4,8'&&blank>=3;$('verdict').textContent=ok?(k==='free'?'The fridge gallery approves.':'Brief met! Now step back: what catches your eye first?'):'Keep playing: '+blank+' empty squares; picture squares at '+(art.map(i=>i+1).join(', ')||'none')+'.';};
$('download').onclick=async()=>{try{await image.decode();const cv=document.createElement('canvas');cv.width=1200;cv.height=1480;const c=cv.getContext('2d');c.fillStyle='#fffcf0';c.fillRect(0,0,1200,1480);c.fillStyle='#242720';c.font='20px monospace';c.fillText('SMALL PRINTS / BIG IDEAS',70,57);const size=340,gap=20;tiles.forEach((t,i)=>{const x=70+(i%3)*(size+gap),y=90+Math.floor(i/3)*(size+gap),ink=inks[t.color];c.save();c.translate(x+size/2,y+size/2);c.rotate(t.rotation*Math.PI/2);c.translate(-size/2,-size/2);c.fillStyle=paper;c.fillRect(0,0,size,size);c.fillStyle=ink;if(t.kind==='art'){const w=image.naturalWidth/3,h=image.naturalHeight/3;c.drawImage(image,(t.crop%3)*w,Math.floor(t.crop/3)*h,w,h,0,0,size,size);}else if(t.kind==='solid')c.fillRect(0,0,size,size);else if(t.kind==='disc'){c.beginPath();c.arc(size/2,size/2,size*.368,0,Math.PI*2);c.fill();}else if(t.kind==='stripe'){c.beginPath();c.moveTo(0,size*.6);c.lineTo(size*.6,0);c.lineTo(size,0);c.lineTo(size,size*.4);c.lineTo(size*.4,size);c.lineTo(0,size);c.closePath();c.fill();}c.restore();});c.fillStyle='#242720';c.font='52px Georgia';const title=$('posterTitle').textContent;const words=title.split(/\s+/);let line='',y=1240;for(const word of words){const next=line?line+' '+word:word;if(c.measureText(next).width>1060&&line){c.fillText(line,70,y);y+=62;line=word;}else line=next;}while(c.measureText(line).width>1060&&c.font!=='24px Georgia'){c.font='24px Georgia';}c.fillText(line,70,y);c.font='16px monospace';c.fillText('NINE SQUARES, ONE SMILE / A COMPOSITION EXPERIMENT',70,1420);cv.toBlob(blob=>{if(!blob){announce('Could not create the poster. Please try again.');return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='nine-squares-poster.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);announce('Your poster is ready. A very respectable fridge acquisition.');},'image/png');}catch(e){announce('The print is not ready. Please wait a moment and try again.');}};
render();brief();
</script></body></html>
